package solution

import "testing"

func TestBinarySearchFound(t *testing.T) {
	nums := []int{1, 3, 5, 7, 9}
	if BinarySearch(nums, 5) != 2 { t.Error("expected index 2") }
	if BinarySearch(nums, 1) != 0 { t.Error("expected index 0") }
	if BinarySearch(nums, 9) != 4 { t.Error("expected index 4") }
}

func TestBinarySearchNotFound(t *testing.T) {
	if BinarySearch([]int{1, 3, 5}, 4) != -1 { t.Error("expected -1") }
}

func TestBinarySearchEmpty(t *testing.T) {
	if BinarySearch([]int{}, 1) != -1 { t.Error("expected -1") }
}

